BEGIN;
INSERT INTO mission_bridge_permissions(key,description) VALUES ('agent.use','Use consented MissionBridge agents'),('agent.review','Review and amend agent output'),('agent.manage','Manage agent prompts and program settings') ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_role_permissions(role_key,permission_key) VALUES ('participant','agent.use'),('mentor','agent.use'),('facilitator','agent.use'),('facilitator','agent.review'),('program_manager','agent.use'),('program_manager','agent.review'),('program_manager','agent.manage'),('safeguarding_officer','agent.review'),('content_editor','agent.use'),('content_editor','agent.review'),('platform_admin','agent.use'),('platform_admin','agent.review'),('platform_admin','agent.manage') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS mission_bridge_prompt_registry(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,agent_key TEXT NOT NULL,prompt_version TEXT NOT NULL,system_prompt TEXT NOT NULL,output_schema JSONB NOT NULL,active BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,agent_key,prompt_version));
CREATE UNIQUE INDEX IF NOT EXISTS idx_mb_prompt_active ON mission_bridge_prompt_registry(tenant_id,agent_key) WHERE active;
CREATE TABLE IF NOT EXISTS mission_bridge_agent_program_settings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,program_id TEXT NOT NULL,ai_enabled BOOLEAN NOT NULL DEFAULT FALSE,auto_messages_enabled BOOLEAN NOT NULL DEFAULT FALSE,updated_by TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,program_id),CHECK(auto_messages_enabled=FALSE));
CREATE TABLE IF NOT EXISTS mission_bridge_agent_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,program_id TEXT,agent_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','human_review_required','approved','rejected','delivered')),request_class TEXT NOT NULL,input_hash TEXT NOT NULL,risk_level TEXT NOT NULL CHECK(risk_level IN('L0','L1','L2','L3')),structured_output JSONB NOT NULL,safety_flags JSONB NOT NULL DEFAULT '[]'::jsonb,human_override_locked BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_model_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,agent_run_id UUID NOT NULL REFERENCES mission_bridge_agent_runs(id),model TEXT NOT NULL,prompt_version TEXT NOT NULL,input_hash TEXT NOT NULL,output JSONB NOT NULL,token_usage JSONB NOT NULL DEFAULT '{}'::jsonb,latency_ms INTEGER NOT NULL DEFAULT 0,safety_flags JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_human_reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,agent_run_id UUID NOT NULL REFERENCES mission_bridge_agent_runs(id),reviewer_user_id TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('approved','amended','rejected')),amended_output JSONB,notes TEXT NOT NULL,revision INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(agent_run_id,revision));
CREATE TABLE IF NOT EXISTS mission_bridge_referral_directory(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,name TEXT NOT NULL,region TEXT NOT NULL,professional_type TEXT NOT NULL,opening_hours TEXT NOT NULL,phone TEXT,address TEXT,source_url TEXT NOT NULL,verified BOOLEAN NOT NULL DEFAULT FALSE,verified_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS mission_bridge_red_team_cases(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),agent_key TEXT NOT NULL,name TEXT NOT NULL,input JSONB NOT NULL,expected_flags JSONB NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_agent_audit_log(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,agent_run_id UUID,actor_user_id TEXT NOT NULL,event_type TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_mb_agent_runs_user ON mission_bridge_agent_runs(tenant_id,user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_mb_agent_reviews ON mission_bridge_human_reviews(tenant_id,agent_run_id,revision DESC);
ALTER TABLE mission_bridge_prompt_registry ENABLE ROW LEVEL SECURITY;ALTER TABLE mission_bridge_agent_program_settings ENABLE ROW LEVEL SECURITY;ALTER TABLE mission_bridge_agent_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE mission_bridge_model_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE mission_bridge_human_reviews ENABLE ROW LEVEL SECURITY;ALTER TABLE mission_bridge_referral_directory ENABLE ROW LEVEL SECURITY;ALTER TABLE mission_bridge_agent_audit_log ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_prompt_registry','mission_bridge_agent_program_settings','mission_bridge_agent_runs','mission_bridge_model_runs','mission_bridge_human_reviews','mission_bridge_referral_directory','mission_bridge_agent_audit_log'] LOOP EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
INSERT INTO mission_bridge_prompt_registry(tenant_id,agent_key,prompt_version,system_prompt,output_schema,active,created_by) VALUES
