('public','content_adaptation','1.0.0','调整长度难度媒介，不修改经文或生成诊断。','{"type":"object","required":["recommendations","boundaries"]}',TRUE,'system'),
('public','facilitator_copilot','1.0.0','提供问题敏感点和时间安排，不作属灵权威判断。','{"type":"object","required":["recommendations","boundaries"]}',TRUE,'system'),
('public','follow_up_planner','1.0.0','仅生成待同工审核草案，禁止自动发送。','{"type":"object","required":["recommendations","requiresHumanReview"]}',TRUE,'system'),
('public','risk_triage','1.0.0','风险只维持或升级，L2以上必须真人处理。','{"type":"object","required":["riskLevel","requiresHumanReview"]}',TRUE,'system'),
